vmax=vmax*1.15;
function xv(v){return margin.left+PW*v/vmax;}
function cyOf(i){return top0+i*(barH+gap)+barH/2;}
function fmt(v){return "$"+Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g,",");}
function computePillWidth(t,fs){return Math.ceil(t.length*fs*0.58)+10;}
var ticks=[0,500,1000,1500];
ticks.forEach(function(t){svg.appendChild(el("line",{x1:xv(t),x2:xv(t),y1:MT,y2:MT+PH,stroke:"#ececec","stroke-width":"0.5"}));});
var refV=rows[0].v;
var refX=xv(refV);
svg.appendChild(el("line",{x1:refX,x2:refX,y1:MT,y2:MT+PH,stroke:"#2e7d32","stroke-width":"1","stroke-dasharray":"3,3"}));
rows.forEach(function(r,i){svg.appendChild(el("rect",{x:margin.left,y:cyOf(i)-barH/2,width:xv(r.v)-margin.left,height:barH,fill:"#4a5568"}));});
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:MT+PH,y2:MT+PH,stroke:"#d8d8d8","stroke-width":"1"}));
svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:MT,y2:MT+PH,stroke:"#d8d8d8","stroke-width":"1"}));
var pillIndex=n-1;
var pillText=fmt(rows[pillIndex].v);
var pillW=computePillWidth(pillText,9);
var pillH=16;
var pillX=xv(rows[pillIndex].v)-pillW-6;
var pillY=cyOf(pillIndex)-pillH/2;
if(pillX<margin.left){pillX=margin.left;}
svg.appendChild(el("rect",{x:pillX,y:pillY,width:pillW,height:pillH,rx:2,fill:"#e8a825"}));
svg.appendChild(mk(pillText,{x:pillX+pillW/2,y:pillY+pillH/2+3.5,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111111"}));
rows.forEach(function(r,i){if(i!==pillIndex){svg.appendChild(mk(fmt(r.v),{x:xv(r.v)-6,y:cyOf(i)+3,"text-anchor":"end","font-size":"8.5","font-weight":"700",fill:"#ffffff"}));}});
rows.forEach(function(r,i){svg.appendChild(mk(r.a,{x:margin.left-6,y:cyOf(i)-1,"text-anchor":"end","font-size":"8",fill:"#444444"}));svg.appendChild(mk(r.b,{x:margin.left-6,y:cyOf(i)+9,"text-anchor":"end","font-size":"7",fill:"#888888"}));});
ticks.forEach(function(t){svg.appendChild(mk(fmt(t),{x:xv(t),y:MT+PH+14,"text-anchor":"middle","font-size":"8",fill:"#999999"}));});
svg.appendChild(mk("14% BRACKET BASELINE",{x:refX+6,y:MT+8,"text-anchor":"start","font-size":"7","font-weight":"700",fill:"#2e7d32"}));
svg.appendChild(mk("Federal tax only. Provincial tax adds to each figure.",{x:margin.left+PW-6,y:MT+PH-6,"text-anchor":"end","font-size":"8",fill:"#444444"}));
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source: CBC News, 2026 federal tax brackets; Aprio, 2026 capital gains inclusion rate of 50%; HDQ calculation. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Each figure is a $10,000 net capital loss multiplied by the 50% inclusion rate and the federal rate for the bracket, before provincial tax. The loss is assumed to offset a taxable capital gain in the same bracket.</p>
<p>A client whose gains fall in the lowest bracket recovers little federally, while a client in the top bracket recovers more than twice as much on the same loss. That difference decides whether a sale is worth the transaction cost and the time out of the market.</p>
<h2>The 61-Day Window Reaches the RRSP, the TFSA and the Spouse</h2>
<p>The superficial loss rule denies a loss when the investor or an affiliated person buys identical property during the 61-day period that runs from 30 days before the sale to 30 days after it, according to Insight Accounting. Affiliated persons include a spouse or common-law partner, a corporation the investor controls, and the investor RRSP and TFSA.</p>
<p>The registered-account case is the costly one. A repurchase inside an RRSP or TFSA denies the loss and, unlike a repurchase in a non-registered account, adds nothing back to the adjusted cost base, so the deduction is destroyed rather than deferred. A client who sells a gold fund in a non-registered account and has a scheduled TFSA contribution that buys the same fund within 30 days has lost the deduction for good.</p>
<h2>Carrybacks and Currency Change the Answer</h2>
<p>Net capital losses can be carried back three years against taxable capital gains on Form T1A or carried forward indefinitely, according to Insight Accounting. A client with taxable gains in a recent year can recover tax already paid instead of waiting for future gains. Gains and losses are calculated in Canadian dollars, so a gold fund bought in U.S. dollars can show a different result from the U.S. dollar price decline alone.</p>
<p>Finance Canada closed its Budget 2026 consultation on September 8 and has not published a release date, so the rules above are current law rather than a forecast. The 92 days to December 30 include a full quarter of market movement, and a loss that exists today may not exist at year-end.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">What They''re Feeling</div>
<p>Clients who bought gold in August feel they made a mistake, and many see a tax deduction as a way to make the loss mean something. Others feel torn between wanting to stay invested in gold and wanting the deduction, without knowing the two can conflict. Clients with large gains elsewhere in the year feel relief that a loss may offset them, mixed with worry about getting the rules wrong.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">What to Say</div>
<div class="script-box">The drop in gold has one useful side effect for your tax return. If you sell gold in a non-registered or corporate account, the loss can offset capital gains, and it can also be carried back three years to recover tax you already paid. Only half of the loss counts, so the tax value is a fraction of the decline, and it depends on your bracket. The trap is the 61-day rule. If you or your spouse, your corporation, your RRSP or your TFSA buys the same investment within 30 days before or after the sale, the loss is denied. If the repurchase happens inside an RRSP or TFSA, the loss is gone permanently. We have until December 30 to place the trade, so there is no reason to rush. I would like to map every account that holds gold and every purchase scheduled in the next two months, then decide whether selling makes sense for your plan.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Who''s Affected</div>
<p><strong>High impact:</strong> Clients holding gold ETFs, bullion certificates or gold miners in non-registered or corporate accounts, especially those with realized gains this year or in the past three years, and couples who fund a spouse TFSA or RRSP with the same funds.</p>
<p><strong>Mixed impact:</strong> Clients in the lowest bracket, who recover about 7 cents federally per dollar of loss and may find the deduction too small to justify a sale.</p>
<p><strong>Potential benefit:</strong> Clients in the top bracket with recent taxable gains, who recover up to 16.5 cents federally per dollar of loss, and corporations with capital gains to offset.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Action Checklist</div>
<div class="checklist-item">List every client holding gold by account type and separate registered from non-registered and corporate holdings.</div>
<div class="checklist-item">Record the adjusted cost base in Canadian dollars for each non-registered gold position.</div>
<div class="checklist-item">Check the last three years of taxable capital gains for each client to confirm carryback room on Form T1A.</div>
<div class="checklist-item">Search spouse, corporate, RRSP and TFSA accounts for purchases of the same or identical funds in the 61-day window.</div>
<div class="checklist-item">Pause automatic contributions or dividend reinvestment into the affected fund before any sale.</div>
<div class="checklist-item">Set a calendar reminder for Wednesday, December 30, the last trade that settles in 2026.</div>
<div class="checklist-item">Document the tax rationale and the client decision in the file.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Follow-Up Email Template</div>
<div class="email-box" id="respond-email">
<strong>Subject:</strong> Your gold position and the year-end tax deadline<br><br>
Hi [Client Name],<br><br>
Thank you for speaking with me today. Here is a short summary.<br><br>
If you sell gold held in a non-registered or corporate account, the resulting capital loss can offset capital gains this year, or gains from the past three years. Only 50% of the loss counts. The last trade that settles in 2026 is on Wednesday, December 30.<br><br>
One rule to keep in mind: if you, your spouse, your corporation, your RRSP or your TFSA buys the same investment within 30 days before or after the sale, the loss is denied. I will review every account and every scheduled purchase before we decide. I have set aside time on [Day and Time] to go through the results with you.<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copy email</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Client Profiles to Target</div>
<p><strong>DIY investors with gold in a non-registered account:</strong> they may sell for the loss without knowing that a repurchase in a TFSA or RRSP, or by a spouse, denies it.</p>
<p><strong>Business owners with corporate investment accounts:</strong> a controlled corporation is affiliated with its owner, so a personal repurchase can deny a corporate loss and the reverse.</p>
<p><strong>Couples who each hold a TFSA and an RRSP:</strong> two sets of registered accounts and automatic contributions create the most ways to trigger the 61-day rule.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Opening Line</div>
<div class="script-box">Gold has fallen about 8% since late August, and if you own it outside an RRSP or TFSA, there is a tax rule that can turn that loss into a deduction or wipe it out completely, depending on what happens in the next 30 days.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Value Proposition</div>
<p>Tax-loss selling looks simple and contains one rule that cannot be undone. A repurchase by the investor, a spouse, a controlled corporation, an RRSP or a TFSA within the 61-day window denies the loss, and inside a registered account the loss is permanently gone. An investor managing money alone has no one to check every account for a matching purchase.</p>
<p>The advisor sees all accounts together, knows the carryback history and can time the trade before December 30. The value is in avoiding the one error that cannot be repaired.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Discovery Questions</div>
<p>1. Which accounts hold gold or gold funds today, and which of them are outside an RRSP or TFSA?</p>
<p>2. Have you realized any capital gains this year or in the last three years?</p>
<p>3. Do you or your spouse have automatic contributions or dividend reinvestment into the same fund?</p>
<p>4. Do you own a corporation that holds investments?</p>
<p>5. Who reviews your tax position before you place a trade?</p>
<p>6. If you sold, would you want to stay invested in gold, and how would you do it without triggering the rule?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Prospecting Email Template</div>
<div class="email-box" id="prospect-email">
<strong>Subject:</strong> A tax rule that can erase your gold loss<br><br>
Hi [Prospect Name],<br><br>
Gold has fallen about 8% since late August. If you hold it outside an RRSP or TFSA, that loss may be deductible, but Canada has a 61-day rule that can deny it, and a repurchase inside an RRSP or TFSA can erase it permanently.<br><br>
I would be glad to walk through the rule and check your accounts, in fifteen minutes and with no obligation. Would [Day] or [Day] work?<br><br>
[Your Name]<br><br>
<em>This communication is for educational purposes only and does not constitute personalized investment advice.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copy email</button>
</div>',
